OWNER_SQL = r"""
CREATE FUNCTION mta.daily_prepared_owner(owner uuid) RETURNS boolean LANGUAGE plpgsql AS $$
BEGIN
 IF owner::text IS DISTINCT FROM nullif(current_setting('fresh.daily_publication_build',true),'') THEN
  RETURN false;
 END IF;
 RETURN EXISTS(SELECT 1 FROM mta.fresh_mta_calculationrun r
 JOIN mta.fresh_mta_dailysourcereceipt s ON s.run_id=r.id
 JOIN mta.fresh_mta_dailyuipublication p ON p.run_id=r.id
 WHERE r.id=owner AND r.kind='DAILY_CHAIN' AND r.status='SUCCEEDED'
 AND r.output_digest<>'' AND r.production_digest<>''
 AND s.input_digest=r.input_digest AND p.output_digest=r.output_digest
 AND p.status='INCOMPLETE' AND p.seal_digest='');
END $$;
"""

def definitions(bodies):
    return '\n'.join('CREATE OR REPLACE FUNCTION mta.' + name +
        '() RETURNS trigger LANGUAGE plpgsql AS $$' + body + '$$;' for name,body in bodies.items())

FORWARD = OWNER_SQL + definitions(PRODUCTION_BODIES)
REVERSE = definitions(ORIGINAL_BODIES) + '\nDROP FUNCTION mta.daily_prepared_owner(uuid);'


def installed_bodies(connection, bodies):
    """Recognize exact additive0054 guards only when that migration is installed.

    Fixture-only installations still require their original exact bodies. A new
    installation must have both the frozen production bodies and exact owner gate.
    """
    with connection.cursor() as cursor:
        cursor.execute("SELECT EXISTS(SELECT 1 FROM django_migrations WHERE app='fresh_mta' AND name='0054_daily_prepared_guards')")
        if not cursor.fetchone()[0]:
            return bodies
        cursor.execute("SELECT p.prosrc,p.prosecdef,l.lanname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='mta' AND p.proname='daily_prepared_owner' AND p.pronargs=1")
        expected=OWNER_SQL.split('AS $$',1)[1].split('$$;',1)[0]
        if cursor.fetchall()!=[(expected,False,'plpgsql')]:
            raise ValueError('Daily prepared owner guard contract differs')
    return {name:PRODUCTION_BODIES.get(name,body) for name,body in bodies.items()}
